<?php
declare(strict_types=1);
namespace App\Services;use App\Repositories\AuditRepository;use PDO;use RuntimeException;use Throwable;
final readonly class BouquetService{public function __construct(private PDO $db,private AuditRepository $audit){}public function save(array $in):int{$id=(int)($in['id']??0);$name=trim((string)($in['name']??''));if($name===''||strlen($name)>150)throw new RuntimeException('Nombre de bouquet inválido.');$categories=array_values(array_unique(array_filter(array_map('intval',(array)($in['category_ids']??[])))));$this->db->beginTransaction();try{if($id)$this->db->prepare('UPDATE bouquets SET name=?,description=?,active=? WHERE id=?')->execute([$name,trim((string)($in['description']??''))?:null,isset($in['active']),$id]);else{$this->db->prepare('INSERT INTO bouquets(name,description,active) VALUES(?,?,?)')->execute([$name,trim((string)($in['description']??''))?:null,isset($in['active'])]);$id=(int)$this->db->lastInsertId();}$this->db->prepare('DELETE FROM bouquet_categories WHERE bouquet_id=?')->execute([$id]);$s=$this->db->prepare('INSERT INTO bouquet_categories(bouquet_id,category_id) VALUES(?,?)');foreach($categories as $c)$s->execute([$id,$c]);$this->db->prepare('DELETE FROM bouquet_content_items WHERE bouquet_id=?')->execute([$id]);$this->db->prepare('INSERT IGNORE INTO bouquet_content_items(bouquet_id,content_item_id) SELECT ?,id FROM content_items WHERE category_id IN (SELECT category_id FROM bouquet_categories WHERE bouquet_id=?)')->execute([$id,$id]);$this->db->commit();$this->audit->record('bouquet.saved','bouquet',$id,['name'=>$name,'categories'=>count($categories)]);return $id;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}public function toggle(int $id):void{$this->db->prepare('UPDATE bouquets SET active=NOT active WHERE id=?')->execute([$id]);$this->audit->record('bouquet.status_toggled','bouquet',$id,[]);}}
